import React, { useState, useEffect } from "react";
import axios from "axios";
import "./CreateGroupPage.css";
import Navbar from "../components/navbar";
import Footer from "../components/footer";
import AdminSidebar from "../components/AdminSideBar";

function CreateGroupPage() {
  const [groupNumber, setGroupNumber] = useState("");
  const [projectName, setProjectName] = useState("");
  const [selectedMembers, setSelectedMembers] = useState([]);
  const [supervisor, setSupervisor] = useState("");
  const [evaluator, setEvaluator] = useState("");
  const [allGroups, setAllGroups] = useState([]);
  const [students, setStudents] = useState([]);
  const [supervisors, setSupervisors] = useState([]);
  const [evaluators, setEvaluators] = useState([]);

  // Fetch data on load
  useEffect(() => {
    const fetchData = async () => {
      try {
        const [studentRes, groupRes, supervisorRes, evaluatorRes] = await Promise.all([
          axios.get("http://localhost:5000/api/student"),
          axios.get("http://localhost:5000/api/group"),
          axios.get("http://localhost:5000/api/facultyAdvisor"),
          axios.get("http://localhost:5000/api/evaluator")
        ]);

        setStudents(studentRes.data.filter(s => !s.isGrouped)); // show only ungrouped students
        setAllGroups(groupRes.data);
        setSupervisors(supervisorRes.data);
        setEvaluators(evaluatorRes.data);
      } catch (err) {
        console.error("Error loading data", err);
      }
    };

    fetchData();
  }, []);

  const handleGroupCreation = async (e) => {
    e.preventDefault();
    if (
      !groupNumber.trim() ||
      !projectName.trim() ||
      selectedMembers.length === 0 ||
      !supervisor ||
      !evaluator
    ) {
      alert("Please fill all fields, select members, supervisor, and evaluator.");
      return;
    }

    try {
      // 1. Create project
      const projectRes = await axios.post("http://localhost:5000/api/project", {
        title: projectName,
        status: "ongoing",
      });

      const projectID = projectRes.data._id;

      // 2. Create group
      const groupRes = await axios.post("http://localhost:5000/api/group", {
        groupNo: groupNumber,
        studentsRegno: selectedMembers.map(s => s.regNo),
        projectID,
        supervisorID: supervisor,
        evaluatorID: evaluator,
      });

      // 3. Update student isGrouped flag
      await Promise.all(selectedMembers.map(s =>
        axios.put(`http://localhost:5000/api/student/regNo/${s.regNo}`, {
          isGrouped: true,
        })
      ));

      alert("Group created successfully!");
      setGroupNumber("");
      setProjectName("");
      setSelectedMembers([]);
      setSupervisor("");
      setEvaluator("");

      // Refresh groups and students
      const [groupRefresh, studentRefresh] = await Promise.all([
        axios.get("http://localhost:5000/api/group"),
        axios.get("http://localhost:5000/api/student"),
      ]);
      setAllGroups(groupRefresh.data);
      setStudents(studentRefresh.data.filter(s => !s.isGrouped));
    } catch (err) {
      console.error("Error creating group", err);
      alert("Group creation failed.");
    }
  };

  const handleMemberSelection = (student) => {
    const alreadySelected = selectedMembers.find(m => m._id === student._id);
    if (alreadySelected) {
      setSelectedMembers(selectedMembers.filter(m => m._id !== student._id));
    } else if (selectedMembers.length < 4) {
      setSelectedMembers([...selectedMembers, student]);
    } else {
      alert("You can select up to 4 members only.");
    }
  };

  const handleDisbandGroup = async (groupId) => {
    if (!window.confirm("Are you sure you want to disband this group?")) return;

    try {
      await axios.delete(`http://localhost:5000/api/group/${groupId}`);
      const [groupRefresh, studentRefresh] = await Promise.all([
        axios.get("http://localhost:5000/api/group"),
        axios.get("http://localhost:5000/api/student"),
      ]);
      setAllGroups(groupRefresh.data);
      setStudents(studentRefresh.data.filter(s => !s.isGrouped));
    } catch (err) {
      console.error("Error disbanding group", err);
      alert("Failed to disband group.");
    }
  };

  return (
    <div className="create-group-container">
      <Navbar />
      <div className="content-wrapper">
        <AdminSidebar />
        <div className="main-content">
          <div className="create-group-section">
            <div className="form-container">
              <h2>Create a New Group</h2>
              <form onSubmit={handleGroupCreation}>
                <div className="input-group">
                  <label>Group Number</label>
                  <input
                    type="text"
                    value={groupNumber}
                    onChange={(e) => setGroupNumber(e.target.value)}
                    placeholder="Enter group number"
                    required
                  />
                </div>
                <div className="input-group">
                  <label>Project Name</label>
                  <input
                    type="text"
                    value={projectName}
                    onChange={(e) => setProjectName(e.target.value)}
                    placeholder="Enter project name"
                    required
                  />
                </div>
                <div className="input-group">
                  <label>Supervisor</label>
                  <select value={supervisor} onChange={(e) => setSupervisor(e.target.value)} required>
                    <option value="">-- Select Supervisor --</option>
                    {supervisors.map(s => (
                      <option key={s._id} value={s._id}>{s.Name}</option>
                    ))}
                  </select>
                </div>
                <div className="input-group">
                  <label>Evaluator</label>
                  <select value={evaluator} onChange={(e) => setEvaluator(e.target.value)} required>
                    <option value="">-- Select Evaluator --</option>
                    {evaluators.map(e => (
                      <option key={e._id} value={e._id}>{e.name}</option>
                    ))}
                  </select>
                </div>
                <button type="submit" className="submit-button">Create Group</button>
              </form>
            </div>

            <div className="student-selection">
              <h3>Select Students</h3>
              <table>
                <thead>
                  <tr>
                    <th>Select</th>
                    <th>Name</th>
                    <th>Reg. No</th>
                  </tr>
                </thead>
                <tbody>
                  {students.map((s) => (
                    <tr key={s._id}>
                      <td>
                        <input
                          type="checkbox"
                          checked={selectedMembers.some(m => m._id === s._id)}
                          onChange={() => handleMemberSelection(s)}
                        />
                      </td>
                      <td>{s.studentName}</td>
                      <td>{s.regNo}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>

            <div className="groups-list">
              <h3>Created Groups</h3>
              {allGroups.length > 0 ? (
                <table>
                  <thead>
                    <tr>
                      <th>Group No</th>
                      <th>Project</th>
                      <th>Supervisor</th>
                      <th>Evaluator</th>
                      <th>Members</th>
                      <th>Action</th>
                    </tr>
                  </thead>
                  <tbody>
                    {allGroups.map((group) => (
                      <tr key={group._id}>
                        <td>{group.groupNo}</td>
                        <td>{group.projectID?.title || "N/A"}</td>
                        <td>{group.supervisorID?.Name || group.supervisorID}</td>
                        <td>{group.evaluatorID?.name || group.evaluatorID}</td>
                        <td>
                          <ul>
                            {group.studentsRegno.map((reg, idx) => (
                              <li key={idx}>{reg}</li>
                            ))}
                          </ul>
                        </td>
                        <td>
                          <button
                            onClick={() => handleDisbandGroup(group._id)}
                            className="disband-button"
                          >
                            Disband
                          </button>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              ) : (
                <p>No groups have been created yet.</p>
              )}
            </div>
          </div>
        </div>
      </div>
      <Footer />
    </div>
  );
}

export default CreateGroupPage;
